"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': "The outlaw Black Bart's Range", 'author': 'Signature original', 'genre': 'Ranch Wars', 'chapters': [{'n': 1, 'title': 'Dust on the Wind', 'text': "Sam Whitaker slept with a letter from the east under the pillow and one eye open. the frontier makes family — out here, that's not a saying. It's the whole law.\n\nThat night in the saloon, the outlaw Black Bart's men made their play: cards, insults, a gun cleared half out of leather. Sam Whitaker ended it without firing — the fast peace, the ranch foreman called it later, shaking their head.\n\nBut a letter from the east changed everything. When Sam Whitaker showed it — a letter from the east, genuine, legal, undeniable — the room went quiet. It was proof. Proof that the outlaw Black Bart's claim was a lie, and lies, in the Rio Bravo valley, have a short life."}, {'n': 2, 'title': 'The Claim', 'text': "the outlaw Black Bart came at noon, as villains do, with lawyers and gunmen in equal number. 'a letter from the east is a forgery,' the outlaw Black Bart declared. 'And forgers hang.' The town watched from windows. the Rio Bravo valley held its breath again.\n\nthe ranch foreman stood with Sam Whitaker — and then the blacksmith, and the schoolteacher, and one by one half the town. 'We know Sam Whitaker's word,' the sheriff said. It wasn't much. It was everything.\n\nThe judge — the outlaw Black Bart's judge — set a hearing for Friday. Three days to prove a letter from the east real, with the outlaw Black Bart's men watching every step. Sam Whitaker smiled the thin smile of someone holding four aces."}, {'n': 3, 'title': 'High Noon', 'text': "the outlaw Black Bart stepped out with two gunmen. 'Last chance,' the outlaw Black Bart said. 'Ride out.' Sam Whitaker thought of the Rio Bravo valley, of the ranch foreman, of every small place that ever needed one person to stand. 'No,' Sam Whitaker said.\n\nFriday noon. The street emptied the way streets do before a storm. Sam Whitaker walked it alone — the ranch foreman had argued, but some walks you take solo. a letter from the east was in the courthouse. This was about more than paper.\n\nWhat happened next took four seconds and would be told for forty years. When the dust settled, the outlaw Black Bart's gunmen were down — winged, not killed; Sam Whitaker never shot to kill if winging would do — and the outlaw Black Bart stood alone, empty-handed."}, {'n': 4, 'title': 'The Drive', 'text': "the outlaw Black Bart's rustlers hit them at the canyon — the last play of a losing hand. The fight was short and decisive: the town rode together, and together is a word the outlaw Black Bart never understood.\n\nSam Whitaker organized the drive: every ranch, every hand, moving the herds to the railhead themselves, cutting out the outlaw Black Bart's middlemen. the ranch foreman rode drag. a letter from the east — the deed — rode in Sam Whitaker's breast pocket, the reason for it all.\n\nThey reached the railhead with the herds and the deed and their heads high. the Rio Bravo valley was solvent. the Rio Bravo valley was free. Sam Whitaker looked back at the dust of the trail and felt the peculiar ache of a job done."}, {'n': 5, 'title': 'Home Range', 'text': "But Sam Whitaker stayed through the winter, helping the ranch foreman mend fences, teaching the kids to read sign, being — for a while — part of the Rio Bravo valley instead of just its defender. It suited them.\n\nthe Rio Bravo valley threw a dance. the ranch foreman danced every dance. The schoolteacher cried. The blacksmith forged a letter from the east's likeness in iron for the courthouse wall — 'so nobody forgets,' he said.\n\na letter from the east stayed in the courthouse, under glass, with the iron likeness beside it. Proof. Promise. the frontier makes family — carved, at the ranch foreman's insistence, on the frame."}, {'n': 6, 'title': 'Sundown', 'text': "the frontier makes family. In the Rio Bravo valley, on the trail, at sundown and sunup. The west remembers.\n\nthe Rio Bravo valley is still there, in the valley, under the big sky. The water runs. The cattle graze. The deed holds. Travelers ask about the iron a letter from the east in the courthouse, and the old-timers tell it true.\n\nSam Whitaker rides somewhere west, where the map goes blank. There are always more valleys, more villains, more folks needing one person to stand. The frontier doesn't end. It just moves."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

